mapper.select:
SELECT p.message_id, p.payload_json FROM t_wecom_kf_pending_message p LEFT JOIN t_wecom_kf_message_retry r ON r.message_id = p.message_id WHERE (r.message_id IS NULL OR (r.failure_count < 6 AND r.next_retry_at <= CURRENT_TIMESTAMP)) AND NOT EXISTS (SELECT 1 FROM t_wecom_kf_message done WHERE done.message_id = p.message_id)
AND p.message_id NOT IN #{id}
ORDER BY p.create_time ASC, p.message_id ASC LIMIT #{limit}
